let exam=null,state=null,partId='listening',records=loadRecords(),urls=new Map(),observer=null,assetEpoch=0,timer=null,lastTick=Date.now(),toastTimer,saveTimer,filters={query:'',kind:'',year:''},reviewingRecord=false,lastSaveOk=true;
let wrongMeta=loadWrongMeta(),wrongSaveOk=true,wrongSession=null,wrongFilters={status:'pending',query:'',type:'',setId:'',page:1};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number.isFinite(n)?Number(n.toFixed(2)).toString():'待自评';
const round=n=>Math.round((n+Number.EPSILON)*100)/100;
