 document.getElementById('result-count').textContent=`${list.length} 套试卷`;document.getElementById('catalog-body').innerHTML=list.length?catalogGroups(list):'<p class="catalog-empty">这个年份暂无试卷，请选择其他年份。</p>';
 if(open){const row=[...ROOT.querySelectorAll('.catalog-fold')].find(d=>d.dataset.catalogEntry===open);if(row)row.open=true}
