function openSet(id,record){const e=record?recordExam(record):getEntry(id);if(!e||record&&!validRecord(record))return;clearTimeout(saveTimer);save();pause();releaseMedia();exam=e;questionNav.open=false;questionNav.active=null;const saved=record||read(DRAFT+entryKey(e),null);reviewingRecord=!!record;state=validRecord(saved)&&entryKey(recordExam(saved))===entryKey(e)?JSON.parse(JSON.stringify(saved)):fresh(e);state.running=false;state.clocks=state.clocks||Object.fromEntries(e.parts.map(p=>[p.partId,(p.minutes||30)*60]));partId=e.parts.some(p=>p.partId===state.partId)?state.partId:orderedParts(e)[0].partId;renderExam();window.scrollTo(0,0)}
function renderExam(){
 releaseMedia();const scored=score(exam,state),notice=uiNotice(exam),partNames={listening:['I','听力','Listening'],reading:['II','阅读','Reading'],writing:['III','写作','Writing'],translation:['IV','翻译','Translation']};
 ROOT.innerHTML=`<div class="exam-layout"><section class="book"><nav class="page-back-row" aria-label="返回导航">${reviewingRecord?backButton('data-attempt="'+state.id+'"','返回成绩详情'):exam.practiceScope?backButton('data-practice-scope="'+exam.practiceScope+'"','返回专项目录'):backButton('data-category="'+(exam.kind==='full-mock'?'full-mock':'practice')+'"','返回试卷列表')}<button class="quiet-home" data-home>返回首页</button></nav><header class="book-header"><div><h1 class="edition-title">${esc(exam.title)}</h1></div><span id="save-status" class="visually-hidden" role="status"></span></header>${notice?`<p class="edition-notice">${esc(notice)}</p>`:''}<div class="exam-history-bar"><button data-history="${entryKey(exam)}">本套历次成绩 (${attemptsFor(entryKey(exam)).length})</button>${state.submitted?`<button data-attempt="${esc(state.id)}">这次的成绩与错题</button>`:''}</div>${state.submitted?receipt():''}<nav class="partnav part-navigation" style="--parts:${exam.parts.length}" aria-label="试卷部分">${orderedParts(exam).map(p=>`<button class="part-tab ${p.partId===partId?'is-active':''}" data-part="${p.partId}" aria-label="${SHORT[p.partId]}" aria-current="${p.partId===partId?'page':'false'}"><span class="part-index">${partNames[p.partId][0]}</span><span class="part-label"><span class="part-zh">${partNames[p.partId][1]}</span><span class="part-en">${partNames[p.partId][2]}</span></span></button>`).join('')}</nav><div class="working-bar"><div class="reading-tools" id="reading-tools" aria-label="阅读题型" ${partId==='reading'&&exam.format==='structured'?'':'hidden'}>${[['A','选词填空'],['B','段落匹配'],['C','仔细阅读']].filter(([letter])=>!PRACTICE_SCOPES[exam.practiceScope]?.section||PRACTICE_SCOPES[exam.practiceScope].section===letter).map(([letter,name])=>`<button class="section-tab ${readingSection()===letter?'is-active':''}" data-section="${letter}" aria-pressed="${readingSection()===letter}"><b>${letter}</b><span>${name}</span></button>`).join('')}</div><div class="time-tools"><span id="progress" class="answer-progress"></span>${exam.audioAsset&&!exam.practiceScope?`<label class="skip-toggle"><input id="skip-audio" type="checkbox" ${state.noAudio?'checked':''} ${state.submitted?'disabled':''}> 本次不做听力</label>`:''}<div class="timer-group"><time class="timer" id="clock">30:00</time><button class="timer-button" id="timer-button" ${state.submitted?'disabled':''}>开始计时</button></div><button class="primary submit-button" id="submit-button">${state.submitted?'重新练习':'交卷并复盘'}</button></div></div><article class="paper" id="paper" aria-label="试卷正文"></article></section>${questionNavigator()}</div><footer class="book-note"><span>CET-4</span></footer>`;
 renderPart(false);updateClock();updateProgress();applyAppearance();
}
function receipt(){const s=score(exam,state),r=s.part710;return`<section class="receipt" aria-label="成绩单"><h2>本次练习结果</h2><div class="total">${s.total710===null?'主观题待自评':fmt(s.total710)+' / '+fmt(s.base)} <span class="small">${s.total710===null?'客观题已得 '+fmt(s.objective710)+' 分':'分'}</span></div><div class="score-list">${orderedParts(exam).map(p=>`<span>${SHORT[p.partId].split(' ')[1]}：${p.partId==='listening'&&state.noAudio?'未参与计分':r[p.partId]===null?'待自评':fmt(r[p.partId])}</span>`).join('')}</div><p class="small muted" style="margin:12px 0 0">${exam.mode==='practice'?'练习成绩，仅按本套实有部分计分。':'练习加权成绩，不代表官方考试报道分。'} 对照参考给写作与翻译评 1–15 原始分后，总分会自动更新。</p></section>`}
