/* Local study tools. No network, AI grading, or changes to exam scoring. */
const STUDY_DATA=JSON.parse(document.getElementById('study-data').textContent);
const STUDY_KEY='cet4.paper.v2.study', CAUSES=['未分类','词汇不熟','没听清','定位偏差','句意理解','粗心误选','时间不足','其他'];
const emptyStudy=()=>({version:1,vocabulary:[],notes:{},checks:{}});
const validDate=x=>typeof x==='string'&&Number.isFinite(Date.parse(x));
const bounded=(x,n)=>typeof x==='string'&&x.length<=n;
const ownObject=x=>x&&typeof x==='object'&&!Array.isArray(x);
function validStudy(x){
 if(!ownObject(x)||x.version!==1||!Array.isArray(x.vocabulary)||x.vocabulary.length>5000||!ownObject(x.notes)||!ownObject(x.checks)||Object.keys(x.notes).length>5000||Object.keys(x.checks).length>10000)return false;
 const ids=new Set();for(const w of x.vocabulary){if(!ownObject(w)||!bounded(w.id,150)||!/^[A-Za-z0-9_-]+$/.test(w.id)||ids.has(w.id)||!bounded(w.word,100)||!w.word.trim()||!bounded(w.meaning,2000)||typeof w.mastered!=='boolean'||!validDate(w.createdAt)||!validDate(w.updatedAt)||!Array.isArray(w.contexts)||w.contexts.length>40)return false;ids.add(w.id);for(const c of w.contexts)if(!ownObject(c)||!BY_ID.has(c.setId)||!(c.number===null||Number.isInteger(c.number)&&c.number>=1&&c.number<=55)||!bounded(c.text,2000)||!validDate(c.at))return false}
 for(const [k,n]of Object.entries(x.notes))if(!wrongContext(k)||!ownObject(n)||!CAUSES.includes(n.cause)||!bounded(n.text,4000)||!validDate(n.updatedAt))return false;
 for(const [k,c]of Object.entries(x.checks))if(!bounded(k,180)||!/:writing$|:translation$/.test(k)||!ownObject(c)||!Array.isArray(c.done)||c.done.some(v=>!['content','structure','language','review'].includes(v))||new Set(c.done).size!==c.done.length||!validDate(c.updatedAt))return false;
 return true;
}
function loadStudy(){const d=read(STUDY_KEY,null);return validStudy(d)?d:emptyStudy()}
let study=loadStudy(),studySaved=true,referenceOnly=false,materialSession=null,wrongView='material',vocabFilter={query:'',status:'all'},selectionEntry=null,compareTo='reference';
function mergeStudy(a,b){
 const out=emptyStudy(),words=new Map();
 for(const w of [...a.vocabulary,...b.vocabulary]){const key=w.word.trim().toLowerCase(),old=words.get(key);if(!old){words.set(key,structuredClone(w));continue}const recent=Date.parse(w.updatedAt)>=Date.parse(old.updatedAt)?w:old,contexts=new Map([...old.contexts,...w.contexts].map(c=>[c.setId+':'+c.number+':'+c.text,c]));words.set(key,{...recent,contexts:[...contexts.values()].slice(-40)})}
 out.vocabulary=[...words.values()];for(const f of ['notes','checks'])for(const [k,v]of [...Object.entries(a[f]),...Object.entries(b[f])])if(!out[f][k]||Date.parse(v.updatedAt)>=Date.parse(out[f][k].updatedAt))out[f][k]=structuredClone(v);return out;
}
function saveStudy(){study=mergeStudy(loadStudy(),study);studySaved=write(STUDY_KEY,study);return studySaved}
