const oldRenderExam=renderExam;renderExam=function(){oldRenderExam();if(!referenceOnly)return;ROOT.querySelector('.receipt')?.remove();const back=ROOT.querySelector('.page-back-row');back.innerHTML=exam.practiceScope?backButton(`data-practice-scope="${exam.practiceScope}"`,'返回专项目录'):backButton(`data-category="${exam.kind==='full-mock'?'full-mock':'practice'}"`,'返回试卷列表');ROOT.querySelector('.exam-history-bar').innerHTML=`<button class="primary" data-new="${entryKey(exam)}">开始练习</button><button data-history="${entryKey(exam)}">历次成绩</button>`;ROOT.querySelector('.time-tools').innerHTML='<span class="small muted">解析浏览</span>';ROOT.querySelector('.question-nav-actions').innerHTML=`<button class="primary" data-new="${entryKey(exam)}">开始练习</button>`;for(const el of ROOT.querySelectorAll('.nav-progress-row,.nav-progress,.nav-legend'))el.hidden=true};
