const oldReview=review;review=function(it,...a){const html=oldReview(it,...a);return referenceOnly?html.replace(/<p class="verdict[^>]*>.*?<\/p>/,`<p class="verdict">正确答案 ${esc(it.answer)}</p>`):html};
const oldProgress=updateProgress;updateProgress=function(){oldProgress();if(referenceOnly&&document.getElementById('save-status'))document.getElementById('save-status').textContent='解析浏览，不保存答卷'};

