const timeText=t=>`${Math.floor(t/60)}:${String(Math.floor(t%60)).padStart(2,'0')}`;
function listeningPanel(e,chosenGroup=null){
 const d=STUDY_DATA.sets[e.setId]||{groups:[],cues:[]},groups=chosenGroup===null?d.groups:d.groups.filter((g,i)=>i===chosenGroup);
 return `<section class="listening-lab" data-listen-set="${e.setId}"><div class="audio-panel"><p>听力复盘</p><audio controls preload="metadata" data-asset="${e.audioAsset}" aria-label="本套听力音频"></audio><div class="listen-controls"><label>播放速度<select data-audio-rate aria-label="播放速度">${[.75,1,1.25,1.5].map(v=>`<option value="${v}" ${v===1?'selected':''}>${v}×</option>`).join('')}</select></label><button data-audio-back>后退 5 秒</button><button data-ab="a">设起点 A</button><button data-ab="b">设终点 B</button><button data-ab="toggle" aria-pressed="false">循环 A–B</button><span class="ab-status" role="status">未设循环区间</span></div></div><p class="listen-note">${d.cues.length?'字幕由本地语音识别生成，可能有误；题组定位为近似时间，可手动调整 A–B。':'本套暂无时间字幕；可阅读原文，手动设置 A–B 复听。'}</p>${groups.length?`<details class="book-transcripts" open><summary>听力原文 · 按材料复盘</summary>${groups.map(g=>`<section class="transcript-group"><div class="transcript-heading"><h3>${groupName(g)}</h3>${Number.isFinite(g.start)?`<button data-audio-window="${g.start},${g.end}">定位并循环此材料</button>`:''}</div><div class="transcript-text">${plain(g.text)}</div></section>`).join('')}</details>`:'<p class="small muted">本套的原文保留在下方原卷解析页中。</p>'}${d.cues.length?`<details class="asr-captions"><summary>辅助时间字幕 · 点击一句复听</summary><label class="caption-follow"><input type="checkbox" data-caption-follow checked> 跟随播放位置</label><div class="caption-list" aria-label="辅助时间字幕">${d.cues.map((c,i)=>`<button data-cue="${i}" data-audio-window="${c[0]},${c[1]}" aria-label="复听 ${timeText(c[0])}：${esc(c[2])}"><time>${timeText(c[0])}</time><span>${esc(c[2])}</span></button>`).join('')}</div></details>`:''}</section>`;
}
const oldAudioPanel=audioPanel;audioPanel=function(){return state.submitted?listeningPanel(exam):oldAudioPanel()};
let player=null,ab={a:null,b:null,on:false},lastCue=-1;
function bindListening(){
 player=ROOT.querySelector('.listening-lab audio');ab={a:null,b:null,on:false};lastCue=-1;if(!player)return;const el=player,lab=el.closest('.listening-lab'),d=STUDY_DATA.sets[lab.dataset.listenSet];
 el.addEventListener('timeupdate',()=>{if(el!==player||!el.isConnected)return;if(ab.on&&Number.isFinite(ab.a)&&Number.isFinite(ab.b)&&el.currentTime>=ab.b){el.currentTime=ab.a;return}const i=d?.cues.findIndex(c=>c[0]<=el.currentTime&&c[1]>el.currentTime)??-1;if(i===lastCue)return;lab.querySelector('[data-cue].is-current')?.classList.remove('is-current');const row=lab.querySelector(`[data-cue="${i}"]`);if(row){row.classList.add('is-current');if(lab.querySelector('.asr-captions')?.open&&lab.querySelector('[data-caption-follow]')?.checked){const box=row.parentElement;if(row.offsetTop<box.scrollTop||row.offsetTop+row.offsetHeight>box.scrollTop+box.clientHeight)box.scrollTo({top:Math.max(0,row.offsetTop-box.offsetTop-box.clientHeight/3),behavior:'instant'})}}lastCue=i});
}
function updateAB(){const lab=player?.closest('.listening-lab');if(!lab)return;lab.querySelector('.ab-status').textContent=ab.a===null?'未设循环区间':`A ${timeText(ab.a)} → ${ab.b===null?'待设终点':timeText(ab.b)}${ab.on?' · 循环中':''}`;lab.querySelector('[data-ab="toggle"]').setAttribute('aria-pressed',String(ab.on))}
function audioWindow(value){if(!player||player.readyState<1){toast('音频正在准备，稍后再试。');return}const [a,b]=value.split(',').map(Number);if(!Number.isFinite(a)||!Number.isFinite(b)||a<0||b<=a)return;ab={a,b:Math.min(b,player.duration),on:true};player.currentTime=a;updateAB();const el=player;el.play().catch(err=>{if(el.isConnected&&err.name!=='AbortError')toast('请点击音频播放器开始播放。')})}

/* Group wrong questions by the actual task/material, never by guessed answer content. */
function materialInfo(e,n){
 const part=e.parts.find(p=>p.partId===(n<=25?'listening':'reading'));
 if(e.format==='structured'){
  if(n<=25){let current='',index=-1,group=[];for(const it of items(e).filter(it=>it.number<=25)){if(it.groupHeader&&it.groupHeader!==current){current=it.groupHeader;index++;group.push({header:current,ns:[]})}if(index<0){index=0;group.push({header:'听力材料',ns:[]})}group[index].ns.push(it.number)}const i=group.findIndex(g=>g.ns.includes(n)),g=group[i];return{key:e.setId+':l'+i,label:g.header,numbers:g.ns,groupIndex:i}}
  const i=(part.tasks||[]).findIndex(t=>t.items.some(x=>x.number===n)),t=part.tasks[i],ns=t.items.map(x=>x.number);return{key:e.setId+':r'+i,label:t.passage?.title|| (n<=35?'选词填空':n<=45?'段落匹配':ns[0]<=46?'Passage One':'Passage Two'),numbers:ns,groupIndex:null};
 }
 const range=n<=25?[1,25]:n<=35?[26,35]:n<=45?[36,45]:n<=50?[46,50]:[51,55];return{key:e.setId+':p'+range[0],label:n<=25?'听力原卷':n<=35?'选词填空':n<=45?'段落匹配':n<=50?'Passage One':'Passage Two',numbers:items(e).filter(it=>it.number>=range[0]&&it.number<=range[1]).map(it=>it.number),groupIndex:null};
}
