const oldWrongList=renderWrongList;renderWrongList=function(){oldWrongList();const list=ROOT.querySelector('.wrongbook-list');if(!list)return;for(const row of list.querySelectorAll('[data-wrong-key]')){const n=study.notes[row.dataset.wrongKey];if(n)row.querySelector('.wrongbook-row-body').insertAdjacentHTML('beforeend',`<p class="note-preview">${esc(n.cause)}${n.text?' · '+esc(n.text):''}</p>`)}if(wrongView!=='material')return;const rows=[...list.children],groups=new Map();for(const row of rows){const g=wrongGroups().find(g=>g.key===row.dataset.wrongKey),m=materialInfo(g.exam,g.number);if(!groups.has(m.key)){const section=document.createElement('section');section.className='wrong-material';section.innerHTML=`<header><div><p>${esc(g.exam.title)}</p><h2>${esc(m.label)}</h2></div><button data-wrong-material="${g.key}">查看材料</button></header>`;groups.set(m.key,section);list.append(section)}groups.get(m.key).append(row)} };
function noteEditor(g){const n=study.notes[g.key]||{cause:'未分类',text:''};return `<section class="error-note" data-note-key="${g.key}"><h3>我的错因</h3><label>主要原因<select data-note-cause>${CAUSES.map(c=>`<option ${n.cause===c?'selected':''}>${c}</option>`).join('')}</select></label><label>下次提醒<textarea data-note-text maxlength="4000" rows="3" placeholder="例如：定位到了相邻段，忽略了转折后的结论。">${esc(n.text)}</textarea></label><div class="note-save-row"><button data-save-note="${g.key}">保存错因</button><span class="note-status" role="status">${studySaved?'只保存在本机':'尚未写入本机，请导出备份'}</span></div></section>`}
