function showMaterial(key){leaveExam();const g=wrongGroups().find(g=>g.key===key);if(!g)return showWrongBook();materialSession=g;const m=materialInfo(g.exam,g.number),related=wrongGroups().filter(x=>materialInfo(x.exam,x.number).key===m.key);ROOT.innerHTML=`<section class="book material-view"><nav class="page-back-row">${backButton('data-wrongbook','返回错题本')}</nav><header class="book-header"><div><h1 class="edition-title">${esc(m.label)}</h1><p>${esc(g.exam.title)}</p></div></header><article id="paper" class="paper">${wrongPassage(g)}<section class="material-questions"><h2>这份材料的错题</h2>${related.map(x=>`<div><strong>第 ${x.number} 题</strong><span>${x.mastered?'已掌握':'待巩固'} · 答错 ${x.events.length} 次</span><button data-wrong-practice="${x.key}">重练</button><button data-wrong-solution="${x.key}">原题与解析</button></div>`).join('')}</section></article></section>`;hydrate();bindListening();applyAppearance();window.scrollTo(0,0)}

/* Personal vocabulary: explicit user meanings, selectable English or manual entry. */
function addVocabulary(word,meaning='',context=null){word=word.trim().replace(/\s+/g,' ');if(!/^[A-Za-z][A-Za-z\s'’\-.,]*$/.test(word)||word.length>100||word.split(/\s+/).length>8){toast('请输入不超过 8 个词的英文单词或短语。');return false}if(study.vocabulary.length>=5000&&!study.vocabulary.some(w=>w.word.toLowerCase()===word.toLowerCase())){toast('生词已达 5000 条，请先导出备份。');return false}const now=new Date().toISOString(),old=study.vocabulary.find(w=>w.word.toLowerCase()===word.toLowerCase());if(old){if(meaning.trim())old.meaning=meaning.trim().slice(0,2000);if(context&&!old.contexts.some(c=>c.setId===context.setId&&c.number===context.number&&c.text===context.text))old.contexts=[...old.contexts,{...context,at:now}].slice(-40);old.updatedAt=now}else study.vocabulary.unshift({id:crypto.randomUUID(),word,meaning:meaning.trim().slice(0,2000),contexts:context?[{...context,at:now}]:[],mastered:false,createdAt:now,updatedAt:now});const ok=saveStudy();studyFeedback(ok,old?'已合并到已有生词':'已加入生词本');return true}
function vocabularyContext(node,text){const e=exam||wrongSession?.exam||materialSession?.exam;if(!e)return null;const q=node?.closest('[data-question]'),n=q?+q.dataset.question:null;let line=(node?.closest('p,.transcript-text,.expl,.distr,legend,.passage')?.textContent||text).trim().replace(/\s+/g,' ');const i=line.toLowerCase().indexOf(text.toLowerCase());if(line.length>1000){const start=Math.max(0,i-250);line=line.slice(start,start+1000)}return{setId:e.setId,number:n,text:line.slice(0,2000)}}
function pickVocabulary(){const sel=window.getSelection(),word=sel?.toString().trim().replace(/\s+/g,' '),node=sel?.anchorNode?.parentElement;if(!word||!node||!ROOT.contains(node)||node.closest('textarea,input,select,button,.quick-filters')||!node.closest('#paper')||!/^[A-Za-z][A-Za-z\s'’\-.,]*$/.test(word)||word.length>100||word.split(/\s+/).length>8){document.getElementById('selection-tools')?.remove();selectionEntry=null;return}const rect=sel.getRangeAt(0).getBoundingClientRect();selectionEntry={word,context:vocabularyContext(node,word)};document.getElementById('selection-tools')?.remove();const el=document.createElement('div');el.id='selection-tools';el.className='selection-tools';el.innerHTML='<button class="primary" data-add-selected>加入生词本</button><button data-close-selection aria-label="关闭取词">×</button>';el.style.left=Math.max(12,Math.min(innerWidth-205,rect.left))+'px';el.style.top=Math.max(8,Math.min(innerHeight-60,rect.bottom+8))+'px';document.body.append(el)}
let selectionTimer;document.addEventListener('selectionchange',()=>{clearTimeout(selectionTimer);selectionTimer=setTimeout(pickVocabulary,180)});
document.addEventListener('pointerdown',ev=>{if(ev.target.closest('#selection-tools'))ev.preventDefault()});
document.addEventListener('click',ev=>{if(ev.target.closest('[data-add-selected]')&&selectionEntry){addVocabulary(selectionEntry.word,'',selectionEntry.context);document.getElementById('selection-tools')?.remove();window.getSelection()?.removeAllRanges()}else if(ev.target.closest('[data-close-selection]')){document.getElementById('selection-tools')?.remove();selectionEntry=null}});
function showVocabulary(){leaveExam();ROOT.innerHTML=`<section class="records vocabulary-page">${backButton('data-home','返回首页')}<header class="wrongbook-heading"><div><h1>生词本</h1><p class="muted">选中试卷中的英文即可收藏，也可以手动添加。</p></div><button id="export-records">导出学习备份</button></header><form class="vocab-add" id="vocab-add"><label>英文单词或短语<input name="word" required maxlength="100" placeholder="例如：take into account" autocomplete="off"></label><label>我的释义<input name="meaning" maxlength="2000" placeholder="可稍后补充"></label><button class="primary" type="submit">添加</button></form><div class="vocab-filters"><label>查找<input id="vocab-query" type="search" value="${esc(vocabFilter.query)}" placeholder="单词、释义或原句"></label><label>状态<select id="vocab-status">${[['all','全部'],['learning','学习中'],['mastered','已掌握']].map(([k,t])=>`<option value="${k}" ${vocabFilter.status===k?'selected':''}>${t}</option>`).join('')}</select></label></div><div id="vocab-list"></div><p class="local-memory-note">释义由你填写。生词、原句、错因与自检可随练习记录一起导出；没有在线查询或数据上传。</p></section>`;document.getElementById('vocab-add').onsubmit=ev=>{ev.preventDefault();const form=ev.target;if(addVocabulary(form.elements.word.value,form.elements.meaning.value)){form.reset();renderVocabulary()}};document.getElementById('vocab-query').oninput=ev=>{vocabFilter.query=ev.target.value;renderVocabulary()};document.getElementById('vocab-status').onchange=ev=>{vocabFilter.status=ev.target.value;renderVocabulary()};renderVocabulary();applyAppearance();window.scrollTo(0,0)}
function renderVocabulary(){
 const q=vocabFilter.query.trim().toLowerCase(),ws=study.vocabulary.filter(w=>(vocabFilter.status==='all'||w.mastered===(vocabFilter.status==='mastered'))&&(!q||[w.word,w.meaning,...w.contexts.map(c=>c.text)].join(' ').toLowerCase().includes(q))).sort((a,b)=>Date.parse(b.updatedAt)-Date.parse(a.updatedAt));
 const contexts=w=>w.contexts.length?`<details class="vocab-contexts" open><summary>原句与练习（${w.contexts.length}）</summary>${w.contexts.map(c=>`<div><p>${plain(c.text)}</p><button data-reference="${c.setId}" ${c.number?'data-ref-question="'+c.number+'"':''}>${esc(BY_ID.get(c.setId).title)}${c.number?' · 第 '+c.number+' 题':''}</button></div>`).join('')}</details>`:'<p class="small muted">手动添加，尚未关联原句。</p>';
 const row=w=>`<article class="vocab-row" data-word-id="${w.id}"><div class="vocab-heading"><h2>${esc(w.word)}</h2><button data-vocab-master="${w.id}" aria-pressed="${w.mastered}">${w.mastered?'已掌握 · 移回学习中':'标记掌握'}</button></div><label class="vocab-meaning">我的释义<textarea rows="2" maxlength="2000" data-vocab-meaning="${w.id}" placeholder="填写你的理解…">${esc(w.meaning)}</textarea></label><button data-vocab-save="${w.id}">保存释义</button>${contexts(w)}</article>`;
 document.getElementById('vocab-list').innerHTML=ws.length?`<p class="small muted">${ws.length} 条</p>${ws.map(row).join('')}`:'<p class="home-empty">'+(study.vocabulary.length?'没有符合条件的生词。':'还没有生词。可以选中试卷里的英文，或在上方添加。')+'</p>';
}

/* Writing and translation comparison, without automatic grading or history mutation. */
const CHECKS={content:'内容完整，切合题目',structure:'结构与衔接清楚',language:'检查语法、用词与拼写',review:'已对照参考修订思路'};
function subjectiveReference(p,e=exam){if(e.format==='structured'){const ref=p.reference||{},order=p.partId==='writing'?['referenceEn','modelEssay','essayTranslation','shenTi','commentary','highlightedExpressions','sentencePatterns']:['referenceEn','keyExpressions','commentary'];return [...new Set([...order,...Object.keys(ref)])].filter(k=>Object.hasOwn(ref,k)&&!['sourcePages','sourcePage','pageBindings','sourceRef'].includes(k)).map(k=>`${fieldName[k]?`<h4>${p.partId==='writing'&&k==='referenceEn'?'参考范文':fieldName[k]}</h4>`:''}${refValue(ref[k])}`).join('')||'<p class="muted">本题暂无参考文本。</p>'}const refs=e.sourcePages.review.filter(x=>(p.referencePages||[]).includes(x.page));return refs.length?`<div class="scan-reference">${refs.map(r=>`<p class="scan-caption">解析第 ${r.page} 页</p><img data-asset="${r.asset}" alt="本题原卷解析第 ${r.page} 页">`).join('')}</div>`:`<p class="muted">${esc(p.referenceUnavailableReason||'本题暂无参考内容。')}</p>`}
function subjectiveHistory(id){return records.filter(r=>r.submitted&&r.id!==state.id&&r.setId===exam.setId&&(r.texts[id]||'').trim()&&recordExam(r).parts.some(p=>p.partId===id)).sort((a,b)=>recordTime(b)-recordTime(a))}
function subjectiveComparison(id){const p=exam.parts.find(p=>p.partId===id);if(referenceOnly)return `<section class="comparison-reference-only"><h3>${id==='writing'?'写作参考':'翻译参考'}</h3>${subjectiveReference(p)}</section>`;const previous=subjectiveHistory(id),r=previous.find(r=>r.id===compareTo),left=state.texts[id]||'',done=study.checks[state.id+':'+id]?.done||[];
 return `<section class="subjective-review"><header class="comparison-heading"><h3>${id==='writing'?'写作对照':'翻译对照'}</h3><label>右侧对照<select data-compare="${id}"><option value="reference" ${!r?'selected':''}>参考与讲解</option>${previous.map(r=>`<option value="${esc(r.id)}" ${compareTo===r.id?'selected':''}>${recordDate(r)} · ${r.ratings[id]?r.ratings[id]+'/15':'未自评'}</option>`).join('')}</select></label></header><div class="comparison-grid"><section class="comparison-column"><h4>本次作答 <span>${wordCount(left)} words</span></h4><div class="my-answer">${left?plain(left):'<span class="muted">本次未填写</span>'}</div></section><section class="comparison-column"><h4>${r?'历史稿件 · '+recordDate(r):'参考与讲解'}</h4><div class="comparison-content">${r?`<div class="my-answer">${plain(r.texts[id])}</div>`:subjectiveReference(p)}</div></section></div><fieldset class="self-checks"><legend>我的检查清单</legend>${Object.entries(CHECKS).map(([k,t])=>`<label><input type="checkbox" data-selfcheck="${k}" data-selfcheck-part="${id}" ${done.includes(k)?'checked':''}>${t}</label>`).join('')}</fieldset><p class="small muted">勾选只用于复盘，不自动打分。下面的自评才会更新本次成绩。</p>${rating(id)}</section>`;
}
const oldEssay=essay;essay=function(id){return state.submitted?subjectiveComparison(id):oldEssay(id)};
const oldStructured=structured;structured=function(p){let html=oldStructured(p);if(state.submitted&&['writing','translation'].includes(partId))html=html.replace(reference(p.reference||{}),'');return html};
const oldSourcePaper=sourcePaper;sourcePaper=function(p){let html=oldSourcePaper(p);if(referenceOnly)html=html.replace(/class="pin ([^"]*)incorrect/g,'class="pin $1').replace(/选择 未作答，答案 /g,'正确答案 ').replace(/<span>答 ([A-Z])<\/span>/g,'<span>答案 $1</span>');if(state.submitted&&['writing','translation'].includes(partId)){const refs=exam.sourcePages.review.filter(x=>(p.referencePages||[]).includes(x.page));if(refs.length){const at=html.lastIndexOf('<details class="reference"><summary>查看本部分原书解析');if(at>=0)html=html.slice(0,at)}}return html};

/* Backups remain compatible with all older record exports. Validate before writing. */
downloadRecords=function(){records=loadRecordsMerged();const payload={schema:'cet4.paper.records.v2',exportedAt:new Date().toISOString(),records,wrongbook:mergeWrongMeta(wrongMeta,loadWrongMeta()),study:mergeStudy(loadStudy(),study)},u=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download='CET4-学习备份-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};
importRecords=async function(file){try{if(file.size>20*1024*1024)throw Error('文件超过 20 MB');const d=JSON.parse(await file.text());if(d.schema!=='cet4.paper.records.v2'||!Array.isArray(d.records)||d.records.length>10000||!d.records.every(validRecord))throw Error('记录格式或内容无效');if(Object.hasOwn(d,'wrongbook')&&!validWrongMeta(d.wrongbook))throw Error('错题本状态无效');if(Object.hasOwn(d,'study')&&!validStudy(d.study))throw Error('生词、错因或自检数据无效');const map=new Map(loadRecords().map(r=>[r.id,r]));for(const r of d.records)if(!map.has(r.id)){r.scoring=score(recordExam(r),r);r.running=false;map.set(r.id,r)}records=[...map.values()];if(!persistRecords(records)){toast('记录尚未写入本机，请导出备份。');return}if(d.wrongbook)wrongMeta=mergeWrongMeta(wrongMeta,d.wrongbook);const wrongOK=!d.wrongbook||saveWrongMeta();if(d.study)study=mergeStudy(study,d.study);const studyOK=!d.study||saveStudy();showRecords();studyFeedback(wrongOK&&studyOK,'学习记录与复盘笔记已导入，已有记录保留。')}catch(e){toast('未导入：'+e.message+'。请使用本页导出的 JSON 文件。')}};
const oldHome=home;home=function(){oldHome();ROOT.querySelector('.home-record-links').insertAdjacentHTML('afterbegin','<button data-vocabulary>生词本</button>')};
const oldAppearance=applyAppearance;applyAppearance=function(){oldAppearance();const el=document.getElementById('vocab-button');if(ROOT.querySelector('.vocabulary-page'))el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');if(materialSession){document.getElementById('font-control').hidden=false;document.getElementById('focus-button').hidden=false;const scale=materialSession.zoom||1,paper=document.getElementById('paper');if(paper){paper.style.setProperty('--reading-size',ui.fontSize+'px');paper.style.setProperty('--scan-scale',scale)}document.getElementById('zoom-row').hidden=materialSession.exam.format!=='source-paper';document.getElementById('zoom-range').value=Math.round(scale*100);document.getElementById('zoom-value').value=Math.round(scale*100)+'%'}};
