/* Restore withheld references only from visually checked, explicitly bound supplements. */
const priorSubjectiveRef=subjectiveReference;subjectiveReference=function(p,e=exam){const r=p.partId==='writing'&&STUDY_DATA.writingRefs?.[e.setId];if(!r)return priorSubjectiveRef(p,e);return `<div class="supplement-reference scan-reference">${r.images.map(img=>{const h=img.bottom-img.top;return`<div class="scan-window"><div class="scan-page" style="aspect-ratio:${img.ratio/h}"><img data-asset="${img.asset}" style="top:${-img.top/h*100}%" alt="本题参考范文与讲解"></div></div>`}).join('')}</div>`};
const priorSourcePaper=sourcePaper;sourcePaper=function(p){let html=priorSourcePaper(p);if(p.partId==='writing'&&STUDY_DATA.writingRefs?.[exam.setId]&&p.referenceUnavailableReason)html=html.replace(`<p class="notice">${esc(p.referenceUnavailableReason)}</p>`,'');return html};

/* Full backups: optional workspace envelope keeps old records.v2 files compatible. */
function collectDrafts(){const map=new Map();try{for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(!k.startsWith(DRAFT))continue;const r=read(k,null);if(validRecord(r)&&!r.submitted&&k===DRAFT+entryKey(recordExam(r)))map.set(entryKey(recordExam(r)),r)}}catch{}if(exam&&state&&!state.submitted&&!referenceOnly&&!reviewingRecord)map.set(entryKey(exam),structuredClone(state));return [...map.values()]}
function collectBackup(){clearTimeout(saveTimer);save();return{schema:'cet4.paper.records.v2',exportedAt:new Date().toISOString(),records:loadRecordsMerged(),wrongbook:mergeWrongMeta(wrongMeta,loadWrongMeta()),study:mergeStudy(loadStudy(),study),workspace:{version:1,drafts:collectDrafts(),preferences:{fontSize:ui.fontSize,theme:ui.theme},learning:mergeLearning(loadLearning(),learning)}}}
function validPreferences(p){return ownObject(p)&&Number.isInteger(p.fontSize)&&p.fontSize>=16&&p.fontSize<=28&&['light','dark'].includes(p.theme)}
function validWorkspace(w){return ownObject(w)&&w.version===1&&Array.isArray(w.drafts)&&w.drafts.length<=482&&w.drafts.every(r=>validRecord(r)&&!r.submitted)&&new Set(w.drafts.map(r=>entryKey(recordExam(r)))).size===w.drafts.length&&validPreferences(w.preferences)&&validLearning(w.learning)}
function validateBackup(d){if(!ownObject(d)||d.schema!=='cet4.paper.records.v2'||!Array.isArray(d.records)||d.records.length>10000||!d.records.every(validRecord))throw Error('练习记录格式无效');if(Object.hasOwn(d,'wrongbook')&&!validWrongMeta(d.wrongbook))throw Error('错题状态无效');if(Object.hasOwn(d,'study')&&!validStudy(d.study))throw Error('生词或笔记无效');if(Object.hasOwn(d,'workspace')&&!validWorkspace(d.workspace))throw Error('草稿或设置无效');return true}
downloadRecords=function(){learning.lastExportAt=new Date().toISOString();saveLearning();const payload=collectBackup(),u=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download='CET4-完整学习备份-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('已发起完整备份下载，请确认文件已保存。')};
importRecords=async function(file){try{if(file.size>20*1024*1024)throw Error('文件超过20MB');const d=JSON.parse(await file.text());validateBackup(d);leaveExam();pendingImport=d;showImportPreview()}catch(e){toast('未导入：'+e.message+'。请选择本页导出的JSON备份。')}};
function showImportPreview(){const d=pendingImport;if(!d)return;ROOT.innerHTML=`<section class="records backup-preview">${backButton('data-cancel-import','取消，返回学习记录')}<h1>确认恢复内容</h1><p class="muted">检查这份备份后再写入本机。现有交卷记录保留，同一ID不重复导入。</p><table><thead><tr><th>内容</th><th>备份包含</th></tr></thead><tbody><tr><td>交卷与练习记录</td><td>${d.records.length} 次</td></tr><tr><td>未交卷草稿</td><td>${d.workspace?.drafts.length||0} 份</td></tr><tr><td>生词</td><td>${d.study?.vocabulary.length||0} 条</td></tr><tr><td>错因笔记</td><td>${Object.keys(d.study?.notes||{}).length} 条</td></tr><tr><td>复习与播放进度</td><td>${d.workspace?'包含':'旧版备份未包含'}</td></tr></tbody></table>${d.workspace?`<fieldset class="restore-options"><legend>恢复选项</legend><label><input type="checkbox" id="restore-drafts" checked> 合并草稿，同一练习保留更新时间较新的稿件</label><label><input type="checkbox" id="restore-preferences" checked> 恢复字号、主题与快捷键设置</label></fieldset>`:'<p class="small muted">这是旧版备份，现有草稿与显示设置保持不变。</p>'}<p id="restore-error" class="notice" role="alert" hidden></p><div class="record-tools"><button class="primary" data-confirm-import>确认恢复</button><button data-cancel-import>取消</button></div></section>`;applyAppearance();window.scrollTo(0,0)}
function commitImport(){
 const d=pendingImport;if(!d)return;validateBackup(d);const writes=new Map(),rs=new Map(loadRecordsMerged().map(r=>[r.id,r]));for(const r of d.records)if(!rs.has(r.id)){const copy=structuredClone(r);copy.scoring=score(recordExam(copy),copy);copy.running=false;rs.set(copy.id,copy)}const all=[...rs.values()];writes.set(RECORDS,all.filter(r=>!r.practiceScope));writes.set(SHARED_RECORDS,all.filter(r=>r.practiceScope));
 if(d.wrongbook)writes.set(WRONGBOOK,mergeWrongMeta(mergeWrongMeta(wrongMeta,loadWrongMeta()),d.wrongbook));if(d.study)writes.set(STUDY_KEY,mergeStudy(mergeStudy(study,loadStudy()),d.study));if(d.workspace){writes.set(LEARNING_KEY,mergeLearning(learning,d.workspace.learning));if(document.getElementById('restore-preferences').checked)writes.set(PREF_KEY,d.workspace.preferences);if(document.getElementById('restore-drafts').checked)for(const incoming of d.workspace.drafts){const key=DRAFT+entryKey(recordExam(incoming)),current=read(key,null),time=r=>Date.parse(r.updatedAt||r.createdAt||'')||0;if(!validRecord(current)||time(incoming)>time(current)){const copy=structuredClone(incoming);copy.running=false;writes.set(key,copy)}}}
 if(d.workspace?.active){const merged=mergeActive(mergeActive(loadActive(),active),d.workspace.active);if(!document.getElementById('restore-preferences').checked)merged.shortcuts=active.shortcuts;if(!validActive(merged))throw Error('合并后的标记或笔记数量超过安全上限，请先导出本机备份。');writes.set(ACTIVE_KEY,merged)}
 const before=new Map(),done=[];try{for(const [k,v]of writes){const text=JSON.stringify(v);before.set(k,localStorage.getItem(k));if(before.get(k)===text)continue;localStorage.setItem(k,text);done.push([k,text])}}catch(e){let restored=true;for(const [k,text]of done.reverse())try{if(localStorage.getItem(k)!==text){restored=false;continue}const old=before.get(k);if(old===null)localStorage.removeItem(k);else localStorage.setItem(k,old)}catch{restored=false}const el=document.getElementById('restore-error');el.hidden=false;el.textContent=restored?'本机存储空间不足或被禁用，本次写入已撤回。请先导出本机数据，再处理空间。':'恢复未完成，部分写入未能撤回。请保留当前页面与备份文件，先导出本机数据。';return}
 records=loadRecords();wrongMeta=loadWrongMeta();study=loadStudy();learning=loadLearning();active=loadActive();const pref=read(PREF_KEY,null);if(validPreferences(pref)){ui.fontSize=pref.fontSize;ui.theme=pref.theme}pendingImport=null;showRecords();toast('恢复完成，现有记录及较新的草稿已保留。');
}

/* Adjustable review intervals; no automatic whole-paper score or mastery changes. */
function dueItems(){const now=Date.now(),out=[];for(const g of wrongGroups()){if(g.mastered)continue;const key='q:'+g.key,s=learning.schedules[key],newError=!s||(Number.isInteger(s.wrongCount)?g.events.length>s.wrongCount:Date.parse(g.last.at)>Date.parse(s.lastAt)),due=newError?0:Date.parse(s.dueAt);out.push({key,kind:'question',g,due,ready:due<=now,rank:g.events.length})}for(const w of study.vocabulary){if(w.mastered)continue;const key='v:'+w.id,s=learning.schedules[key],due=s?Date.parse(s.dueAt):0;out.push({key,kind:'word',w,due,ready:due<=now,rank:0})}return out.sort((a,b)=>a.due-b.due||b.rank-a.rank||a.key.localeCompare(b.key))}
function reviewHome(){const due=dueItems().filter(x=>x.ready),u=due.filter(x=>x.uncertain).length,q=due.filter(x=>x.kind==='question'&&!x.uncertain).length,v=due.length-q-u;return`<section class="review-home"><div><h2>今天待复习</h2><p>${due.length?`${q} 道错题 · ${u} 道不确定题 · ${v} 条生词`:'今天暂时没有待复习内容'}</p></div><div><button class="${due.length?'primary':''}" data-review-queue>${due.length?'开始复习':'查看复习安排'}</button><button data-learning-analysis>学习分析</button></div></section>`}
function showReviewQueue(){queueSession=null;leaveExam();const due=dueItems(),ready=due.filter(x=>x.ready),future=due.filter(x=>!x.ready);ROOT.innerHTML=`<section class="records review-queue">${backButton('data-home','返回首页')}<h1>待复习</h1><p class="muted">优先处理到期内容；错题按材料连续练习，生词先回忆再看释义。</p><div class="queue-options"><label>内容<select id="queue-kind"><option value="all">题目与生词</option><option value="question">错题与不确定题</option><option value="word">只复习生词</option></select></label><label>本轮数量<select id="queue-count"><option>5</option><option selected>10</option><option>20</option></select></label><label>复习间隔<select id="review-interval">${[['standard','标准：1 / 3 / 7 / 14天'],['dense','密集：1 / 2 / 4 / 7天'],['relaxed','宽松：2 / 5 / 10 / 20天']].map(([k,t])=>`<option value="${k}" ${learning.interval===k?'selected':''}>${t}</option>`).join('')}</select></label></div><p>${ready.length} 项待复习 · ${future.length} 项尚未到期</p><button class="primary" data-start-queue ${ready.length?'':'disabled'}>开始本轮</button>${ready.length?`<div class="due-list">${ready.slice(0,30).map(x=>`<div><span>${x.kind==='question'?esc(x.g.exam.title)+' · 第 '+x.g.number+' 题':esc(x.w.word)}</span><small>${x.uncertain?'不确定题 · 自主收录':x.kind==='question'?x.g.type+' · 累计答错 '+x.g.events.length+' 次':'生词'}${x.due?' · '+new Date(x.due).toLocaleDateString('zh-CN')+' 到期':' · 首次复习'}</small></div>`).join('')}</div>`:'<p class="home-empty">先完成练习、收录错题或添加生词，之后在这里复习。</p>'}${future.length?`<details class="future-reviews"><summary>查看之后的安排</summary>${future.slice(0,30).map(x=>`<p>${x.kind==='word'?esc(x.w.word):esc(x.g.exam.title)+' · '+x.g.number+'题'} · ${new Date(x.due).toLocaleDateString('zh-CN')}</p>`).join('')}</details>`:''}<p class="local-memory-note">间隔是可调整的学习安排。错题的“已掌握”仍由你单独标记，原交卷成绩保持不变。</p></section>`;applyAppearance();window.scrollTo(0,0)}
function startReviewQueue(){const kind=document.getElementById('queue-kind').value,limit=+document.getElementById('queue-count').value;let selected=dueItems().filter(x=>x.ready&&(kind==='all'||x.kind===kind));if(!selected.length){toast('当前筛选没有到期内容。');return}selected=selected.slice(0,limit);const grouped=new Map();for(const x of selected){const k=x.kind==='question'?materialInfo(x.g.exam,x.g.number).key:'vocabulary';if(!grouped.has(k))grouped.set(k,[]);grouped.get(k).push(x)}queueSession={items:[...grouped.values()].flat(),index:0,results:[],revealed:false};showQueueItem()}
