function queueGradeButtons(){return`<button data-queue-grade="again">还不熟，${INTERVALS[learning.interval][0]}天后再练</button><button class="primary" data-queue-grade="remembered">记住了，安排下次</button>`}
function queueGrade(grade){const s=queueSession;if(!s)return;const x=s.items[s.index],old=learning.schedules[x.key],now=new Date(),level=grade==='again'?0:Math.min(3,(old?.level??-1)+1),days=INTERVALS[learning.interval][level];learning.schedules[x.key]={level,lastAt:now.toISOString(),dueAt:new Date(+now+days*86400000).toISOString(),updatedAt:now.toISOString()};if(x.kind==='question')learning.schedules[x.key].wrongCount=wrongGroups().find(g=>g.key===x.g.key)?.events.length||x.g.events.length;const saved=saveLearning();s.results.push({key:x.key,grade,days});s.index++;s.revealed=false;showQueueItem();if(!saved)toast('复习安排尚未写入本机，请导出备份。')}
function finishQueue(){const s=queueSession;leaveExam();queueSession=null;ROOT.innerHTML=`<section class="records queue-finished">${backButton('data-home','返回首页')}<h1>本轮复习完成</h1><p>${s.results.length} 项已整理，${s.results.filter(x=>x.grade==='again').length} 项需要再巩固。</p><p class="muted">下次复习已按当前间隔安排。原交卷成绩与掌握标记保持不变。</p><button class="primary" data-review-queue>查看复习安排</button><button id="export-records">导出完整备份</button></section>`;applyAppearance();window.scrollTo(0,0)}
const beforeQueueRender=renderWrongQuestion;renderWrongQuestion=function(){beforeQueueRender();if(!queueSession)return;const x=queueSession.items[queueSession.index];if(x?.kind!=='question'||x.g.key!==wrongSession?.key)return;ROOT.querySelector('.page-back-row').innerHTML=backButton('data-stop-queue','结束本轮，返回安排');ROOT.querySelector('.wrong-practice-note').textContent=`本轮 ${queueSession.index+1} / ${queueSession.items.length} · 单题复习不改变原交卷成绩`;if(wrongSession.checked)ROOT.querySelector('.wrong-practice-actions').insertAdjacentHTML('afterend',`<section class="queue-grade"><p>安排下一次复习</p>${queueGradeButtons()}</section>`)};

/* Text-first analytics: compatible bases stay separate; blanks are not wrong answers. */
function analysisData(){const rs=loadRecordsMerged().filter(r=>r.submitted&&r.mode===analysisFilter.mode&&(analysisFilter.days==='all'||recordTime(r)>=Date.now()-+analysisFilter.days*86400000)),types=['听力','选词填空','段落匹配','仔细阅读'],stats=Object.fromEntries(types.map(t=>[t,{correct:0,wrong:0,blank:0}]));for(const r of rs)for(const row of attemptStats(recordExam(r),r).rows)if(row.status!=='skipped'){const s=stats[row.type];if(row.status==='correct')s.correct++;else if(row.status==='wrong')s.wrong++;else s.blank++}return{rs,stats}}
function showLearningAnalysis(){queueSession=null;leaveExam();const {rs,stats}=analysisData(),entryMap=new Map();for(const r of rs){const e=recordExam(r),s=score(e,r),key=entryKey(e)+'|'+s.base;if(!entryMap.has(key))entryMap.set(key,{e,base:s.base})}if(!entryMap.has(analysisFilter.entry))analysisFilter.entry=entryMap.keys().next().value||'';const selected=entryMap.get(analysisFilter.entry),recent=rs.filter(r=>selected&&entryKey(recordExam(r))===entryKey(selected.e)&&score(recordExam(r),r).base===selected.base).sort((a,b)=>recordTime(b)-recordTime(a)).slice(0,5);
 const weak=Object.entries(stats).filter(([t,s])=>s.correct+s.wrong>=5).sort((a,b)=>a[1].correct/(a[1].correct+a[1].wrong)-b[1].correct/(b[1].correct+b[1].wrong))[0],scope={听力:'listening',选词填空:'cloze',段落匹配:'matching',仔细阅读:'careful'};const suggestion=weak?rs.slice().sort((a,b)=>recordTime(b)-recordTime(a)).map(r=>getEntry(r.setId,scope[weak[0]])).find(Boolean):null;
 const ids=new Set(rs.map(r=>r.setId)),recordIds=new Set(rs.map(r=>r.id)),repeated=wrongGroups().map(g=>({...g,events:g.events.filter(ev=>ev.recordId&&recordIds.has(ev.recordId))})).filter(g=>g.events.length).sort((a,b)=>b.events.length-a.events.length).slice(0,8),causes={};for(const [key,n]of Object.entries(study.notes)){if(ids.has(wrongContext(key)?.exam.setId)&&n.cause!=='未分类')causes[n.cause]=(causes[n.cause]||0)+1}
 ROOT.innerHTML=`<section class="records learning-analysis">${backButton('data-home','返回首页')}<h1>学习分析</h1><div class="analysis-filters"><label>练习范围<select id="analysis-mode"><option value="full-mock" ${analysisFilter.mode==='full-mock'?'selected':''}>完整模考</option><option value="practice" ${analysisFilter.mode==='practice'?'selected':''}>专项与综合练习</option></select></label><label>时间<select id="analysis-days">${[['all','全部时间'],['30','最近30天'],['7','最近7天']].map(([v,t])=>`<option value="${v}" ${analysisFilter.days===v?'selected':''}>${t}</option>`).join('')}</select></label></div><p class="small muted">${rs.length} 次交卷。正确率按实际作答次数计算，重复练习分别计入；未答和跳过听力单列。</p><h2>各题型表现</h2><div class="table-scroll"><table><thead><tr><th>题型</th><th>答对 / 已答</th><th>正确率</th><th>未答</th></tr></thead><tbody>${Object.entries(stats).map(([t,s])=>`<tr><td>${t}</td><td>${s.correct} / ${s.correct+s.wrong}</td><td>${s.correct+s.wrong?Math.round(100*s.correct/(s.correct+s.wrong))+'%':'暂无'}</td><td>${s.blank}</td></tr>`).join('')}</tbody></table></div>${weak?`<div class="study-suggestion"><p>当前记录中，${weak[0]}的正确率最低，可优先复习这一项。</p>${suggestion?`<button data-new="${entryKey(suggestion)}">练${weak[0]}</button>`:''}<button data-review-queue>复习到期错题</button></div>`:'<p class="muted">某题型至少有5次有效作答后，再给出练习建议。</p>'}<h2>最近五次成绩</h2><label class="history-filter">同套、同计分上限<select id="analysis-entry"><option value="">请选择</option>${[...entryMap].map(([k,v])=>`<option value="${k}" ${k===analysisFilter.entry?'selected':''}>${esc(v.e.title)} · ${fmt(v.base)}分</option>`).join('')}</select></label>${recent.length?`<div class="table-scroll"><table><thead><tr><th>交卷时间</th><th>成绩</th><th>答错 / 未答</th><th>回看</th></tr></thead><tbody>${recent.map(r=>{const e=recordExam(r),s=attemptStats(e,r);return`<tr><td>${recordDate(r)}</td><td>${scoreText(e,r)}</td><td>${s.wrong} / ${s.unanswered}</td><td><button data-attempt="${esc(r.id)}">查看</button></td></tr>`}).join('')}</tbody></table></div>`:'<p class="home-empty">还没有可比较的交卷记录。</p>'}<h2>反复答错的题</h2>${repeated.length?`<div class="repeat-list">${repeated.map(g=>`<div><span>${esc(g.exam.title)} · 第${g.number}题</span><small>答错 ${g.events.length} 次</small><button data-wrong-solution="${g.key}">复盘</button></div>`).join('')}</div>`:'<p class="muted">本范围还没有错题。</p>'}<h2>我记录的错因</h2>${Object.keys(causes).length?`<p>${Object.entries(causes).sort((a,b)=>b[1]-a[1]).map(([k,n])=>esc(k)+' '+n+'题').join(' · ')}</p>`:'<p class="muted">保存错因笔记后，这里会整理你自己的分类。</p>'}<p class="local-memory-note">自评未完成的总分保持“待自评”；不同上限不比较总分，不折算成710。</p></section>`;for(const [id,key]of [['analysis-mode','mode'],['analysis-days','days'],['analysis-entry','entry']])document.getElementById(id).onchange=ev=>{analysisFilter[key]=ev.target.value;showLearningAnalysis()};applyAppearance();window.scrollTo(0,0)}

const beforeLearningHome=home;home=function(){queueSession=null;beforeLearningHome();ROOT.querySelector('.home-mode-grid').insertAdjacentHTML('afterend',reviewHome());const note=ROOT.querySelector('.local-memory-note');note.insertAdjacentHTML('beforebegin',`<p class="backup-reminder">${learning.lastExportAt?'上次发起备份：'+new Date(learning.lastExportAt).toLocaleDateString('zh-CN'):'还没有导出完整备份'} <button id="export-records">导出完整备份</button></p>`)};
