/* Deliberate practice. Supplemental local data never rewrites exam answers or grades. */
const ACTIVE_DATA=JSON.parse(document.getElementById('active-data').textContent),ACTIVE_KEY='cet4.paper.v2.active';
const emptyActive=()=>({version:1,flags:{},annotations:{},pageNotes:{},dictationDrafts:{},dictationAttempts:[],revisions:{},uncertainSchedules:{},shortcuts:{enabled:false,updatedAt:'1970-01-01T00:00:00.000Z'}});
const safeId=x=>typeof x==='string'&&/^[A-Za-z0-9_-]{1,150}$/.test(x)&&!['__proto__','constructor','prototype'].includes(x),stamp=()=>new Date().toISOString();
function dictationClip(sid,id){return ACTIVE_DATA.dictation[sid]?.clips.find(c=>c.id===id)}
function validActive(d){
 if(!ownObject(d)||d.version!==1||!ownObject(d.shortcuts)||typeof d.shortcuts.enabled!=='boolean'||!validDate(d.shortcuts.updatedAt)||!Array.isArray(d.dictationAttempts)||d.dictationAttempts.length>10000)return false;
 for(const k of ['flags','annotations','pageNotes','dictationDrafts','revisions','uncertainSchedules'])if(!ownObject(d[k]))return false;
 if(Object.keys(d.flags).length>30000||Object.keys(d.annotations).length>5000||Object.keys(d.pageNotes).length>5000||Object.keys(d.dictationDrafts).length>5000||Object.keys(d.revisions).length>1000||Object.keys(d.uncertainSchedules).length>5000)return false;
 for(const [key,f]of Object.entries(d.flags)){const e=getEntry(f?.setId,f?.practiceScope);if(!ownObject(f)||!e||!bounded(f.recordId,150)||!f.recordId||!Number.isInteger(f.number)||!items(e).some(it=>it.number===f.number)||key!==f.recordId+':'+f.number||!['uncertain','later','review'].every(k=>typeof f[k]==='boolean')||!validDate(f.updatedAt))return false}
 for(const [id,a]of Object.entries(d.annotations))if(!safeId(id)||!ownObject(a)||a.id!==id||!BY_ID.has(a.setId)||!bounded(a.anchor,150)||!a.anchor.startsWith(a.setId+'|reading|')||!Number.isInteger(a.start)||!Number.isInteger(a.end)||a.start<0||a.end>a.start+2000||a.end<=a.start||a.end>500000||!bounded(a.quote,2000)||a.quote.length!==a.end-a.start||!bounded(a.note,4000)||typeof a.longSentence!=='boolean'||typeof a.deleted!=='boolean'||Object.hasOwn(a,'markStyle')&&!['underline','highlight'].includes(a.markStyle)||!validDate(a.updatedAt))return false;
 for(const [key,n]of Object.entries(d.pageNotes)){const e=BY_ID.get(n?.setId),p=e?.parts.find(p=>p.partId===n?.partId);if(!ownObject(n)||e?.format!=='source-paper'||!p?.paperPages.some(p=>p.page===n.page)||key!==n.setId+'|'+n.partId+'|'+n.page||!bounded(n.note,4000)||!validDate(n.updatedAt))return false}
 for(const [key,q]of Object.entries(d.dictationDrafts))if(!ownObject(q)||!BY_ID.get(q.setId)?.audioAsset||!(q.clipId==='manual'||dictationClip(q.setId,q.clipId))||key!==q.setId+'|'+q.clipId||!bounded(q.text,6000)||!validDate(q.updatedAt))return false;
 for(const q of d.dictationAttempts)if(!ownObject(q)||!safeId(q.id)||!dictationClip(q.setId,q.clipId)||!bounded(q.text,6000)||!validDate(q.at))return false;
 for(const [id,r]of Object.entries(d.revisions)){const e=getEntry(r?.setId,r?.practiceScope);if(!safeId(id)||!ownObject(r)||r.id!==id||!e||!['writing','translation'].includes(r.partId)||!e.parts.some(p=>p.partId===r.partId)||!bounded(r.recordId,150)||!r.recordId||!bounded(r.baseText,100000)||!bounded(r.text,100000)||!bounded(r.reason,4000)||!validDate(r.createdAt)||!validDate(r.updatedAt))return false}
 for(const [key,s]of Object.entries(d.uncertainSchedules))if(!wrongContext(key)||!ownObject(s)||!Number.isInteger(s.level)||s.level<0||s.level>3||!validDate(s.lastAt)||!validDate(s.dueAt)||!validDate(s.seenFlagAt)||!validDate(s.updatedAt))return false;
 return true;
}
function loadActive(){const d=read(ACTIVE_KEY,null);return validActive(d)?d:emptyActive()}
let active=loadActive(),activeSaved=true,annotationSelection=null,annotationCandidate=null,annotationSaveTimer=null,revisionSession=null,dictationSession=null,uncertainSession=null,activeSaveTimer=null;
function mergeActive(a,b){const out=emptyActive();for(const f of ['flags','annotations','pageNotes','dictationDrafts','revisions','uncertainSchedules'])for(const [k,v]of [...Object.entries(a[f]),...Object.entries(b[f])])if(!out[f][k]||Date.parse(v.updatedAt)>=Date.parse(out[f][k].updatedAt))out[f][k]=structuredClone(v);const map=new Map([...a.dictationAttempts,...b.dictationAttempts].map(x=>[x.id,x]));out.dictationAttempts=[...map.values()];out.shortcuts=Date.parse(b.shortcuts.updatedAt)>=Date.parse(a.shortcuts.updatedAt)?{...b.shortcuts}:{...a.shortcuts};return out}
function saveActive(){active=mergeActive(loadActive(),active);activeSaved=write(ACTIVE_KEY,active);return activeSaved}
function activeReadingSession(){return !!(revisionSession||dictationSession||uncertainSession)}
function flushActiveDrafts(){flushAnnotationDrafts();clearTimeout(activeSaveTimer);if(revisionSession){const r=active.revisions[revisionSession.id],text=document.getElementById('revision-text'),reason=document.getElementById('revision-reason');if(r&&text&&(r.text!==text.value||r.reason!==reason.value)){r.text=text.value;r.reason=reason.value;r.updatedAt=stamp();saveActive()}}if(dictationSession){const input=document.getElementById('dictation-text');if(input){dictationSession.text=input.value;saveDictationDraft()}}}
const activePriorLeave=leaveExam;leaveExam=function(){flushActiveDrafts();closeAnnotationEditor();activePriorLeave();annotationSelection=null;revisionSession=null;dictationSession=null;uncertainSession=null};
const activePriorOpen=openSet;openSet=function(...args){flushActiveDrafts();closeAnnotationEditor();revisionSession=null;dictationSession=null;uncertainSession=null;return activePriorOpen(...args)};
const activePriorNew=startNew;startNew=function(...args){flushActiveDrafts();closeAnnotationEditor();revisionSession=null;dictationSession=null;uncertainSession=null;return activePriorNew(...args)};
const activePriorCollect=collectBackup;collectBackup=function(){flushActiveDrafts();const d=activePriorCollect();d.workspace.active=mergeActive(loadActive(),active);return d};
const activePriorWorkspace=validWorkspace;validWorkspace=function(w){return activePriorWorkspace(w)&&(!Object.hasOwn(w,'active')||validActive(w.active))};
const activePriorPreview=showImportPreview;showImportPreview=function(){activePriorPreview();const d=pendingImport?.workspace?.active;if(!d)return;ROOT.querySelector('tbody').insertAdjacentHTML('beforeend',`<tr><td>题目标记</td><td>${Object.values(d.flags).filter(f=>f.uncertain||f.later).length} 项</td></tr><tr><td>批注与页码笔记</td><td>${Object.values(d.annotations).filter(a=>!a.deleted).length+Object.keys(d.pageNotes).length} 条</td></tr><tr><td>听写与修订稿</td><td>${d.dictationAttempts.length} 次听写 / ${Object.keys(d.revisions).length} 份修订</td></tr>`)};

/* Per-attempt uncertainty/later marks. They are not wrong-answer events. */
function flagKey(r,n){return r.id+':'+n}
function currentFlag(n){return active.flags[flagKey(state,n)]}
function relevantNumbers(){if(!exam)return[];return partItems(partId).filter(it=>partId!=='reading'||exam.format!=='structured'||(readingSection()==='A'?it.number<=35:readingSection()==='B'?it.number>=36&&it.number<=45:it.number>=46))}
function markedNumber(){const list=relevantNumbers();return list.some(it=>it.number===questionNav.active)?questionNav.active:list[0]?.number}
function toggleQuestionFlag(n,field){if(!exam||!state||referenceOnly||(n<=25&&state.noAudio)||!items().some(it=>it.number===n))return;const key=flagKey(state,n);if(!active.flags[key]&&Object.keys(active.flags).length>=30000)return toast('题目标记已达上限，请先导出备份。');const f=active.flags[key]||{recordId:state.id,setId:exam.setId,number:n,uncertain:false,later:false,review:false,...(exam.practiceScope?{practiceScope:exam.practiceScope}:{})};f[field]=!f[field];if(!f.uncertain)f.review=false;f.updatedAt=stamp();active.flags[key]=f;studyFeedback(saveActive(),field==='review'?(f.review?'已加入不确定题复习':'已移出不确定题复习'):'题目标记已保存');updateMarkPanel();updateQuestionNavigator();if(ROOT.querySelector('.flag-sheet'))showFlags()}
function markPanel(){if(referenceOnly||!state||(partId==='listening'&&state.noAudio)||!['listening','reading'].includes(partId)||!relevantNumbers().length)return'';const n=markedNumber(),f=currentFlag(n)||{};return`<section class="mark-panel" aria-label="题目标记"><label>当前题<select id="mark-question">${relevantNumbers().map(it=>`<option value="${it.number}" ${it.number===n?'selected':''}>第 ${it.number} 题</option>`).join('')}</select></label><div><button data-flag="uncertain" data-flag-number="${n}" aria-pressed="${!!f.uncertain}">不确定</button><button data-flag="later" data-flag-number="${n}" aria-pressed="${!!f.later}">稍后再看</button><button data-show-flags>查看本次标记</button>${state.submitted&&f.uncertain?`<button data-flag="review" data-flag-number="${n}" aria-pressed="${!!f.review}">${f.review?'已在复习 · 移出':'加入不确定题复习'}</button>`:''}</div></section>`}
function updateMarkPanel(){const el=ROOT.querySelector('.mark-panel');if(el)el.outerHTML=markPanel()}
function showFlags(){if(!state||referenceOnly)return;ROOT.querySelector('.flag-sheet')?.remove();const fs=Object.values(active.flags).filter(f=>f.recordId===state.id&&(f.uncertain||f.later));ROOT.querySelector('#paper').insertAdjacentHTML('afterbegin',`<section class="flag-sheet"><header><h3>本次标记</h3><button data-close-flags>收起</button></header>${fs.length?fs.sort((a,b)=>a.number-b.number).map(f=>{const it=items().find(it=>it.number===f.number),result=state.submitted?(state.answers[f.number]===it.answer?'已答对':state.answers[f.number]?'答错':'未答'):'';return`<div><button data-flag-jump="${f.number}">第 ${f.number} 题</button><span>${[f.uncertain?'不确定':'',f.later?'稍后再看':'',result].filter(Boolean).join(' · ')}</span>${state.submitted&&f.uncertain?`<button data-flag="review" data-flag-number="${f.number}" aria-pressed="${f.review}">${f.review?'已加入复习':'加入复习'}</button>`:''}</div>`}).join(''):'<p class="muted">还没有标记。选择当前题后，可标为“不确定”或“稍后再看”。</p>'}</section>`);ROOT.querySelector('.flag-sheet').scrollIntoView({block:'start'})}
const activePriorNav=updateQuestionNavigator;updateQuestionNavigator=function(){activePriorNav();if(!state||referenceOnly)return;ROOT.querySelectorAll('[data-nav-question]').forEach(b=>{const f=currentFlag(+b.dataset.navQuestion);b.classList.toggle('is-uncertain',!!f?.uncertain);b.classList.toggle('is-later',!!f?.later);if(f?.uncertain||f?.later)b.setAttribute('aria-label',b.getAttribute('aria-label')+(f?.uncertain?'，不确定':'')+(f?.later?'，稍后再看':''))});updateMarkPanel()};
const activePriorDue=dueItems;dueItems=function(){const base=activePriorDue(),known=new Set(base.filter(x=>x.kind==='question').map(x=>x.g.key)),rs=new Map(loadRecordsMerged().filter(r=>r.submitted).map(r=>[r.id,r])),flags=new Map();for(const f of Object.values(active.flags)){if(!f.uncertain||!f.review||!rs.has(f.recordId))continue;const key=f.setId+':'+f.number;if(!flags.has(key)||Date.parse(f.updatedAt)>Date.parse(flags.get(key).updatedAt))flags.set(key,f)}for(const [key,f]of flags){if(known.has(key))continue;const e=getEntry(f.setId,f.practiceScope),it=items(e).find(it=>it.number===f.number),s=active.uncertainSchedules[key],due=!s||Date.parse(f.updatedAt)>Date.parse(s.seenFlagAt)?0:Date.parse(s.dueAt);base.push({key:'u:'+key,kind:'question',uncertain:true,flagKey:f.recordId+':'+f.number,g:{key,exam:e,number:f.number,item:it,type:wrongType(f.number),events:[]},due,ready:due<=Date.now(),rank:0})}return base.sort((a,b)=>a.due-b.due||b.rank-a.rank||a.key.localeCompare(b.key))};
const activePriorQueueView=showQueueItem;showQueueItem=function(){const x=queueSession?.items[queueSession.index];if(!x?.uncertain)return activePriorQueueView();openUncertain(x.flagKey,true)};
const activePriorQueueGrade=queueGrade;queueGrade=function(grade){const s=queueSession,x=s?.items[s.index];if(!x?.uncertain)return activePriorQueueGrade(grade);const now=stamp(),old=active.uncertainSchedules[x.g.key],level=grade==='again'?0:Math.min(3,(old?.level??-1)+1),days=INTERVALS[learning.interval][level];active.uncertainSchedules[x.g.key]={level,lastAt:now,dueAt:new Date(Date.now()+days*86400000).toISOString(),seenFlagAt:active.flags[x.flagKey].updatedAt,updatedAt:now};const ok=saveActive();s.results.push({key:x.key,grade,days});s.index++;showQueueItem();if(!ok)toast('复习安排尚未写入本机，请导出备份。')};
function openUncertain(key,queued=false){const f=active.flags[key];if(!f)return;const s=queueSession;leaveExam();if(queued)queueSession=s;uncertainSession={key,exam:getEntry(f.setId,f.practiceScope),number:f.number,choice:'',checked:false};renderUncertain();window.scrollTo(0,0)}
function renderUncertain(){const s=uncertainSession,e=s.exam,it=items(e).find(it=>it.number===s.number),g={exam:e,item:it,number:s.number};releaseMedia();ROOT.innerHTML=`<section class="book uncertain-review"><nav class="page-back-row">${backButton('data-review-queue','返回复习安排')}</nav><header class="book-header"><div><h1 class="edition-title">第 ${s.number} 题 · 不确定题复习</h1><p>${esc(e.title)}</p></div></header><article id="paper" class="paper"><p class="small muted">这题因你标记“不确定”而收录，不代表原答卷答错。</p>${wrongPassage(g)}<section class="question" data-question="${s.number}"><fieldset><legend>${s.number}. ${esc(it.stemEn||'请结合原题选择答案。')}</legend>${it.options?`<div class="options">${it.options.map(o=>`<label class="option ${s.choice===o.letter?'chosen':''}"><input type="radio" name="uncertain-answer" data-uncertain-answer value="${o.letter}" ${s.choice===o.letter?'checked':''} ${s.checked?'disabled':''}><span>${o.letter}) ${esc(o.textEn)}</span></label>`).join('')}</div>`:`<label>选择答案<select data-uncertain-answer ${s.checked?'disabled':''}><option value="">请选择</option>${[...letters(it,e)].map(l=>`<option ${s.choice===l?'selected':''}>${l}</option>`).join('')}</select></label>`}</fieldset>${s.checked?`${e.format==='structured'?review(it,{[s.number]:s.choice}):`<p>正确答案 ${it.answer}。原书解析请在本套解析页查看。</p>`}<section class="queue-grade">${queueGradeButtons()}</section>`:'<button class="primary" data-check-uncertain>检查本次作答</button>'}</section></article></section>`;hydrate();bindListening();applyAppearance()}

