function anchorNodes(root){const out=[],walk=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode:n=>n.parentElement.closest('button,select,input,textarea,.annotation-editor')?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT});while(walk.nextNode())out.push(walk.currentNode);return out}
function anchorText(root){return anchorNodes(root).map(n=>n.textContent).join('')}
function anchorRange(root,start,end){let pos=0,a=null,b=null;for(const node of anchorNodes(root)){const next=pos+node.length;if(!a&&start>=pos&&start<next)a=[node,start-pos];if(end>pos&&end<=next){b=[node,end-pos];break}pos=next}if(!a||!b)return null;const r=document.createRange();r.setStart(...a);r.setEnd(...b);return r}
function prepareAnchors(){if(!exam||partId!=='reading'||exam.format!=='structured')return;ROOT.querySelectorAll('#paper .passage').forEach((el,i)=>el.dataset.textAnchor=exam.setId+'|reading|'+readingSection()+'|'+i);restoreAnnotations()}
