/* Word-level alignment is local text comparison, never semantic or AI grading. */
function wordTokens(t){return t.normalize('NFKC').replace(/’/g,"'").match(/[A-Za-z0-9]+(?:['-][A-Za-z0-9]+)*/g)||[]}
function alignWords(before,after,fold=false){const a=wordTokens(before),b=wordTokens(after);if(a.length>600||b.length>600)return null;const same=(x,y)=>fold?x.toLowerCase()===y.toLowerCase():x===y,m=a.length,n=b.length,rows=Array.from({length:m+1},()=>new Uint16Array(n+1));for(let i=0;i<=m;i++)rows[i][0]=i;for(let j=0;j<=n;j++)rows[0][j]=j;for(let i=1;i<=m;i++)for(let j=1;j<=n;j++)rows[i][j]=Math.min(rows[i-1][j]+1,rows[i][j-1]+1,rows[i-1][j-1]+(same(a[i-1],b[j-1])?0:1));let i=m,j=n,ops=[];while(i||j){if(i&&j&&rows[i][j]===rows[i-1][j-1]+(same(a[i-1],b[j-1])?0:1)){ops.push({type:same(a[i-1],b[j-1])?'same':'replace',old:a[--i],text:b[--j]})}else if(i&&rows[i][j]===rows[i-1][j]+1)ops.push({type:'missing',old:a[--i]});else ops.push({type:'extra',text:b[--j]})}ops.reverse();return{ops,referenceWords:m,correct:ops.filter(o=>o.type==='same').length,missing:ops.filter(o=>o.type==='missing').length,replaced:ops.filter(o=>o.type==='replace').length,extra:ops.filter(o=>o.type==='extra').length}}
function diffHTML(d){return d.ops.map(o=>o.type==='same'?esc(o.text):o.type==='missing'?`<del>${esc(o.old)}</del>`:o.type==='extra'?`<ins>${esc(o.text)}</ins>`:`<del>${esc(o.old)}</del> <ins>${esc(o.text)}</ins>`).join(' ')}
function showDictation(sid,clipId){if(!BY_ID.get(sid)?.audioAsset)return;leaveExam();const clips=ACTIVE_DATA.dictation[sid].clips,clip=clipId==='manual'?null:clips.find(c=>c.id===clipId)||clips[0]||null,key=sid+'|'+(clip?.id||'manual'),draft=active.dictationDrafts[key];dictationSession={setId:sid,clipId:clip?.id||'manual',text:draft?.text||'',checked:false,revealed:false,loop:false,a:clip?.start??null,b:clip?.end??null};renderDictation();window.scrollTo(0,0)}
function saveDictationDraft(){const s=dictationSession;if(!s)return;const key=s.setId+'|'+s.clipId,old=active.dictationDrafts[key];if(old?.text===s.text)return;active.dictationDrafts[key]={setId:s.setId,clipId:s.clipId,text:s.text,updatedAt:stamp()};saveActive()}
function dictationFeedback(){const s=dictationSession,clip=dictationClip(s.setId,s.clipId);if(!s.revealed)return'';if(!clip){const groups=STUDY_DATA.sets[s.setId].groups,e=BY_ID.get(s.setId),p=e.parts.find(p=>p.partId==='listening');return`<section class="dictation-feedback"><h3>手动核对</h3><p class="small muted">本段没有可靠的逐句标准答案，不自动评判。</p>${groups.length?groups.map(g=>`<h4>${groupName(g)}</h4><div class="reference-text">${esc(g.text)}</div>`).join(''):`<div class="scan-reference">${e.sourcePages.review.filter(pg=>(p.referencePages||[]).includes(pg.page)).map(pg=>`<img data-asset="${pg.asset}" alt="本套听力原卷解析第${pg.page}页">`).join('')}</div>`}</section>`}const d=s.checked?alignWords(clip.answer,s.text,true):null;return`<section class="dictation-feedback"><h3>原文对照</h3><div class="reference-text">${esc(clip.answer)}</div>${d?`<p>原文词命中 ${d.correct} / ${d.referenceWords} · 漏写 ${d.missing} · 替换 ${d.replaced} · 多写 ${d.extra}</p><p class="word-diff">${diffHTML(d)}</p><p class="small muted">删除线是原文中漏写或被替换的词，下划线是你多写或替换后的词。忽略大小写与标点，不判断同义表达；不计入模考成绩。</p>`:''}</section>`}
function renderDictation(){releaseMedia();const s=dictationSession,e=BY_ID.get(s.setId),clips=ACTIVE_DATA.dictation[s.setId].clips,clip=dictationClip(s.setId,s.clipId);ROOT.innerHTML=`<section class="book dictation-view"><nav class="page-back-row">${backButton('data-exit-dictation','返回本套听力解析')}</nav><header class="book-header"><div><h1 class="edition-title">听写练习</h1><p>${esc(e.title)}</p></div></header><article id="paper" class="paper"><label class="dictation-picker">片段<select id="dictation-clip">${clips.map((c,i)=>`<option value="${c.id}" ${c.id===s.clipId?'selected':''}>${c.groupLabel} · 片段 ${i+1}（${Math.round(c.end-c.start)}秒）</option>`).join('')}<option value="manual" ${s.clipId==='manual'?'selected':''}>手动选段 · 自行核对</option></select></label><p class="small muted">${clip?'参考文字取自已收录原文。时间段由辅助识别对齐，可用A/B调整复听边界。':'可手动设置A/B，听后对照原文或原卷图片；不使用识别字幕自动判分。'}</p><audio controls preload="metadata" data-asset="${e.audioAsset}" aria-label="听写音频"></audio><div class="dictation-controls"><button class="primary" data-play-dictation>播放本段</button><button data-dictation-ab="a">设起点 A</button><button data-dictation-ab="b">设终点 B</button><label><input type="checkbox" id="dictation-loop"> 循环复听</label><label>倍速<select id="dictation-rate">${[.75,1,1.25,1.5].map(v=>`<option ${v===1?'selected':''}>${v}</option>`).join('')}</select></label><span id="dictation-window">${s.a!==null?'A '+timeText(s.a)+' → '+(s.b===null?'待设终点':timeText(s.b)):'尚未设置区间'}</span></div><label class="dictation-answer">输入听到的内容<textarea id="dictation-text" maxlength="6000" rows="6" spellcheck="false" placeholder="先听再写，检查后才显示原文。">${esc(s.text)}</textarea></label><p id="dictation-save-status" class="small muted">听写草稿单独保存在本机。</p><div class="dictation-actions"><button class="primary" data-check-dictation ${clip?'':'disabled'}>检查听写</button><button data-reveal-dictation>直接看原文</button><button data-clear-dictation>清空本次输入</button></div><div id="dictation-feedback">${dictationFeedback()}</div><details class="dictation-history"><summary>本套最近听写记录</summary>${active.dictationAttempts.filter(a=>a.setId===s.setId).slice(-10).reverse().map(a=>`<p>${new Date(a.at).toLocaleString('zh-CN')} · ${dictationClip(a.setId,a.clipId)?.groupLabel} · ${wordTokens(a.text).length}词</p>`).join('')||'<p class="muted">尚无检查记录。</p>'}</details></article></section>`;hydrate();const audio=ROOT.querySelector('audio');audio.addEventListener('loadedmetadata',()=>{if(s.a!==null)audio.currentTime=Math.min(s.a,audio.duration)});audio.addEventListener('timeupdate',()=>{if(s.b!==null&&audio.currentTime>=s.b&&!audio.paused){if(s.loop){audio.currentTime=s.a||0;audio.play().catch(()=>{})}else audio.pause()}});applyAppearance()}
function checkDictation(){const s=dictationSession,clip=dictationClip(s.setId,s.clipId);if(!clip||!s.text.trim()){toast('先输入听到的内容，或选择“直接看原文”。');return}if(wordTokens(s.text).length>600){toast('本段输入较长，请缩短到600词以内后再比较。');return}s.checked=true;s.revealed=true;const last=active.dictationAttempts.at(-1);if((!last||last.setId!==s.setId||last.clipId!==s.clipId||last.text!==s.text)&&active.dictationAttempts.length<10000)active.dictationAttempts.push({id:crypto.randomUUID(),setId:s.setId,clipId:s.clipId,text:s.text,at:stamp()});saveActive();ROOT.querySelector('#dictation-feedback').innerHTML=dictationFeedback();ROOT.querySelector('#dictation-feedback').scrollIntoView({block:'center'})}

/* Revisions are independent editable documents; original attempts remain immutable. */
function openRevision(recordId,id=null){const r=loadRecordsMerged().find(r=>r.id===recordId&&r.submitted);if(!r)return;const e=recordExam(r),part=id?active.revisions[id]?.partId:state?.id===recordId?partId:undefined;if(!['writing','translation'].includes(part))return;leaveExam();let rev=id&&active.revisions[id];if(!rev){if(Object.keys(active.revisions).length>=1000)return toast('修订稿数量已达上限，请先导出备份。');rev={id:crypto.randomUUID(),recordId:r.id,setId:r.setId,...(r.practiceScope?{practiceScope:r.practiceScope}:{}),partId:part,baseText:r.texts[part]||'',text:r.texts[part]||'',reason:'',createdAt:stamp(),updatedAt:stamp()};active.revisions[rev.id]=rev;saveActive()}revisionSession={id:rev.id,exam:e,zoom:1};renderRevision();window.scrollTo(0,0)}
function renderRevision(){releaseMedia();const s=revisionSession,r=active.revisions[s.id],p=s.exam.parts.find(p=>p.partId===r.partId);ROOT.innerHTML=`<section class="book revision-view"><nav class="page-back-row">${backButton('data-exit-revision','返回原交卷复盘')}</nav><header class="book-header"><div><h1 class="edition-title">${r.partId==='writing'?'作文':'译文'}二次改稿</h1><p>${esc(s.exam.title)}</p></div></header><article id="paper" class="paper"><p class="small muted">原稿和原成绩保留。这里单独保存修订，不自动打分。</p><div class="revision-grid"><section><h3>原交卷稿</h3><div class="reference-text">${r.baseText?esc(r.baseText):'原交卷未填写'}</div></section><section><label>本版修订<textarea id="revision-text" maxlength="100000" rows="12" spellcheck="false">${esc(r.text)}</textarea></label><p id="revision-word-count" class="small muted">${wordCount(r.text)} words</p></section></div><label class="revision-reason">这次为什么这样改？<textarea id="revision-reason" maxlength="4000" rows="3" placeholder="例如：把结论提前，删掉了偏题的例子。">${esc(r.reason)}</textarea></label><div class="revision-actions"><button data-save-revision>保存当前修订</button><button class="primary" data-diff-revision>查看词语增删</button><button data-copy-revision>以当前稿另存一版</button></div><p id="revision-save-status" class="small muted">修订稿自动保存。</p><div id="revision-diff"></div><details class="reference"><summary>查看本题参考与讲解</summary>${subjectiveReference(p,s.exam)}</details></article></section>`;hydrate();applyAppearance()}
function revisionDiff(){flushActiveDrafts();const r=active.revisions[revisionSession.id],d=alignWords(r.baseText,r.text,false);document.getElementById('revision-diff').innerHTML=d?`<section class="revision-diff"><h3>词语改动</h3><p class="small muted">删除线表示原稿删去的词，下划线表示新增或替换后的词；正文对照仍保留原段落与标点。</p><div class="word-diff">${diffHTML(d)}</div></section>`:'<p class="notice">文字较长，保留左右全文对照，不生成逐词增删。</p>'}

