const activePriorRenderPart=renderPart;renderPart=function(...args){closeAnnotationEditor();activePriorRenderPart(...args);const paper=ROOT.querySelector('#paper');paper.tabIndex=0;const panel=markPanel();if(panel)paper.querySelector('.part-heading').insertAdjacentHTML('afterend',panel);paper.insertAdjacentHTML('beforeend',pageNotePanel());loadPageNote();prepareAnchors();if(partId==='listening'&&exam.audioAsset)paper.querySelector('.audio-panel')?.insertAdjacentHTML('beforebegin',`<div class="active-listening-entry"><button data-dictation="${exam.setId}">听写练习</button></div>`);if(state.submitted&&!referenceOnly&&['writing','translation'].includes(partId)){const rows=Object.values(active.revisions).filter(r=>r.recordId===state.id&&r.partId===partId).sort((a,b)=>Date.parse(b.updatedAt)-Date.parse(a.updatedAt));paper.querySelector('.subjective-review').insertAdjacentHTML('beforeend',`<section class="revision-list"><h3>我的修订稿</h3><button class="primary" data-new-revision>保留原稿，另存修订</button>${rows.map(r=>`<div><span>${new Date(r.updatedAt).toLocaleString('zh-CN')} · ${wordCount(r.text)}词</span><button data-open-revision="${r.id}">继续改稿</button></div>`).join('')}</section>`)}if(!referenceOnly&&state&&Object.values(active.flags).some(f=>f.recordId===state.id&&(f.uncertain||f.later)))paper.querySelector('.part-heading').insertAdjacentHTML('afterend','<button class="flag-summary-button" data-show-flags>回看本次不确定／稍后题</button>')};
