/* Finite icon feedback only: native button actions and keyboard activation stay intact. */
(()=>{
 const reduced=matchMedia('(prefers-reduced-motion: reduce)'),running=new Set(),last=new WeakMap();
 function feedback(button){
  if(!button?.isConnected||button.disabled||document.hidden||reduced.matches)return;
  let targets=[],frames,duration=420;
  if(button.id==='records-button'){targets=[...button.querySelectorAll('svg')];frames=[{transform:'rotate(0deg)'},{transform:'rotate(360deg)'}];duration=520}
  else if(button.id==='theme-button'){targets=[...button.querySelectorAll('svg')];frames=[{transform:'rotate(-28deg) scale(.8)'},{transform:'rotate(12deg) scale(1.1)',offset:.65},{transform:'rotate(0deg) scale(1)'}]}
  else if(button.matches('.part-tab')){targets=[...button.querySelectorAll('.part-index')];frames=[{transform:'translateY(0)'},{transform:'translateY(-4px)',offset:.38},{transform:'translateY(1px)',offset:.72},{transform:'translateY(0)'}]}
  else if(button.matches('#catalog-button,#wrongbook-button,#vocab-button,.simple-mode-card,.question-nav-toggle')){targets=[...button.querySelectorAll('svg:not(.mode-arrow)')];frames=[{transform:'rotate(0deg) translateY(0)'},{transform:'rotate(-12deg) translateY(-2px)',offset:.3},{transform:'rotate(8deg) translateY(0)',offset:.65},{transform:'rotate(0deg) translateY(0)'}]}
  if(!targets.length)return;
  for(const animation of last.get(button)||[])animation.cancel();
  const group=targets.map(target=>{const animation=target.animate(frames,{duration,easing:'cubic-bezier(.2,.7,.25,1)',iterations:1});running.add(animation);const done=()=>running.delete(animation);animation.addEventListener('finish',done,{once:true});animation.addEventListener('cancel',done,{once:true});return animation});last.set(button,group);
 }
 document.addEventListener('click',event=>{
  const button=event.target.closest?.('button');if(!button||button.disabled)return;
  const id=button.id,part=button.dataset.part;
  requestAnimationFrame(()=>feedback(button.isConnected?button:id?document.getElementById(id):part?ROOT.querySelector(`button[data-part="${part}"]`):null));
 },true);
 const stop=()=>{for(const animation of [...running])animation.cancel()};
 reduced.addEventListener('change',()=>{if(reduced.matches)stop()});document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});
})();

